def stability_sum(items, *, min_items: int = 1) -> dict:
    """Aggregate rank-change stability across named scenario runs.

    ``items`` must be a non-empty list of mappings, each with exactly the
    keys ``name, result`` in that order.  ``name`` is a unique non-empty
    str and ``result`` is a complete :func:`rank_change_stability` result
    (schema ``climate-grid/wrc-stability-v1``) with exactly the keys
    ``schema, windows, scenarios, data`` in that order; every member is
    validated against that contract, including each row's key order
    ``scenario, count, reversals, longest_run, stable_rate, level`` and
    the row invariants.  Every item's result must share the same
    ``windows`` and ``scenarios`` in the same order; both are taken from
    the first item.  ``min_items`` must be a non-bool positive int.

    For every scenario (in scenario order) the rows whose ``level`` is
    not ``None`` are collected across items: ``total`` is ``len(items)``,
    ``valid`` is the number of collected rows, ``missing`` is
    ``(total - valid) / total`` and ``levels`` counts the collected rows
    at each of the levels ``stable, low, medium, high`` in that order.
    When ``valid < min_items``, ``rate`` and ``uncertainty`` are both
    ``None``; otherwise, with ``W`` the sum of the collected rows'
    ``count``, ``rate`` is ``sum(count * stable_rate) / W`` and
    ``uncertainty`` is
    ``sqrt(sum(count * (stable_rate - rate) ** 2) / W)``.

    The returned mapping uses the key order ``schema, windows, scenarios,
    items, data``; ``schema`` is ``climate-grid/ws-v1``, both axes echo
    the first item's result and ``items`` lists the item names in item
    order.  ``data`` follows the scenario order; each row uses the key
    order ``scenario, total, valid, missing, levels, rate, uncertainty``.
    ``total``, ``valid`` and the ``levels`` counts are ints and every
    output float is ``round(x, 12)`` with negative zero normalized to
    ``0.0``.  The input is not modified.

    Raises ``TypeError`` for wrong container/item/argument types and
    ``ValueError`` for any other contract violation.
    """
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    if len(items) == 0:
        raise ValueError("items must be non-empty")

    names: list[str] = []
    validated: list[list] = []
    seen_names: set[str] = set()
    for index, item in enumerate(items):
        where = f"items[{index}]"
        if not isinstance(item, dict):
            raise TypeError(f"{where} must be a dict")
        if tuple(item.keys()) != _STABILITY_SUM_ITEM_KEYS:
            raise ValueError(
                f"{where} must have exactly the keys name, result in order"
            )

        name = item["name"]
        if not isinstance(name, str):
            raise TypeError(f"{where}.name must be a str")
        if name == "":
            raise ValueError(f"{where}.name must be non-empty")
        if name in seen_names:
            raise ValueError(f"duplicate items name: {name!r}")
        seen_names.add(name)

        windows, scenarios, data = _validate_rank_change_stability(
            item["result"], where=f"{where}.result"
        )
        if not validated:
            first_windows = windows
            first_scenarios = scenarios
        else:
            if windows != first_windows:
                raise ValueError(
                    "all items must share the same result windows in the "
                    "same order, taken from the first item"
                )
            if scenarios != first_scenarios:
                raise ValueError(
                    "all items must share the same result scenarios in the "
                    "same order, taken from the first item"
                )

        names.append(name)
        validated.append(data)

    if not isinstance(min_items, int) or isinstance(min_items, bool):
        raise TypeError("min_items must be a non-bool int")
    if min_items < 1:
        raise ValueError("min_items must be positive")

    total = len(items)
    result_rows = []
    for s_index, scenario in enumerate(first_scenarios):
        rows = [data[s_index] for data in validated]
        present = [row for row in rows if row["level"] is not None]
        valid = len(present)
        missing = _round_output((total - valid) / total)
        levels = [
            sum(1 for row in present if row["level"] == level)
            for level in _STABILITY_LEVELS
        ]

        if valid < min_items:
            rate = None
            uncertainty = None
        else:
            weight = sum(row["count"] for row in present)
            rate_value = (
                sum(row["count"] * row["stable_rate"] for row in present)
                / weight
            )
            uncertainty_value = math.sqrt(
                sum(
                    row["count"] * (row["stable_rate"] - rate_value) ** 2
                    for row in present
                )
                / weight
            )
            rate = _round_output(rate_value)
            uncertainty = _round_output(uncertainty_value)

        result_rows.append(
            {
                "scenario": scenario,
                "total": total,
                "valid": valid,
                "missing": missing,
                "levels": levels,
                "rate": rate,
                "uncertainty": uncertainty,
            }
        )

    return {
        "schema": _STABILITY_SUM_SCHEMA,
        "windows": list(first_windows),
        "scenarios": list(first_scenarios),
        "items": names,
        "data": result_rows,
    }


def _validate_stability_sum(
    result: Any, *, where: str = "result"
) -> tuple[list[str], list[str], list[str], list]:
    """Validate a complete :func:`stability_sum` result.

    Returns the window names, the scenario order, the item names and the
    ``data`` rows.
    """
    if not isinstance(result, dict):
        raise TypeError(f"{where} must be a dict")
    if tuple(result.keys()) != _SCALE_DELTA_RESULT_KEYS:
        raise ValueError(
            f"{where} must have exactly the keys schema, windows, "
            "scenarios, items, data in order"
        )

    schema = result["schema"]
    if not isinstance(schema, str):
        raise TypeError(f"{where}.schema must be a str")
    if schema != _STABILITY_SUM_SCHEMA:
        raise ValueError(
            f"{where}.schema must be {_STABILITY_SUM_SCHEMA!r}"
        )

    windows = _validate_string_list(
        result["windows"], f"{where}.windows", minimum=2
    )
    scenarios = _validate_string_list(result["scenarios"], f"{where}.scenarios")
    items = _validate_string_list(result["items"], f"{where}.items")

    data = result["data"]
    if not isinstance(data, list):
        raise TypeError(f"{where}.data must be a list")
    if len(data) != len(scenarios):
        raise ValueError(
            f"{where}.data must have {len(scenarios)} rows (one per "
            "scenario, in scenario order)"
        )

    for index, row in enumerate(data):
        row_where = f"{where}.data[{index}]"
        if not isinstance(row, dict):
            raise TypeError(f"{row_where} must be a dict")
        if tuple(row.keys()) != _SCALE_DELTA_ROW_KEYS:
            raise ValueError(
                f"{row_where} must have exactly the keys scenario, total, "
                "valid, missing, levels, rate, uncertainty in order"
            )

        scenario = row["scenario"]
        if not isinstance(scenario, str):
            raise TypeError(f"{row_where}.scenario must be a str")
        if scenario != scenarios[index]:
            raise ValueError(
                f"{row_where}.scenario must be {scenarios[index]!r} for its "
                "scenario-order position"
            )

        total = row["total"]
        if not isinstance(total, int) or isinstance(total, bool):
            raise TypeError(f"{row_where}.total must be a non-bool int")
        if total != len(items):
            raise ValueError(
                f"{row_where}.total must equal the number of items"
            )

        valid = row["valid"]
        if not isinstance(valid, int) or isinstance(valid, bool):
            raise TypeError(f"{row_where}.valid must be a non-bool int")
        if not 0 <= valid <= total:
            raise ValueError(
                f"{row_where}.valid must be between 0 and {row_where}.total"
            )

        _validate_number(row["missing"], f"{row_where}.missing", nullable=False)
        if not 0 <= row["missing"] <= 1:
            raise ValueError(f"{row_where}.missing must be between 0 and 1")

        levels = row["levels"]
        if not isinstance(levels, list):
            raise TypeError(f"{row_where}.levels must be a list")
        if len(levels) != len(_STABILITY_LEVELS):
            raise ValueError(
                f"{row_where}.levels must have {len(_STABILITY_LEVELS)} "
                "counts (stable, low, medium, high)"
            )
        for level_index, count in enumerate(levels):
            if not isinstance(count, int) or isinstance(count, bool):
                raise TypeError(
                    f"{row_where}.levels[{level_index}] must be a non-bool int"
                )
            if count < 0:
                raise ValueError(
                    f"{row_where}.levels[{level_index}] must be non-negative"
                )
        if sum(levels) != valid:
            raise ValueError(
                f"{row_where}.levels must sum to {row_where}.valid"
            )

        rate = row["rate"]
        uncertainty = row["uncertainty"]
        if rate is None or uncertainty is None:
            if rate is not None or uncertainty is not None:
                raise ValueError(
                    f"{row_where}: rate and uncertainty must be both None "
                    "or both present"
                )
            continue

        if valid == 0:
            raise ValueError(
                f"{row_where}: rate and uncertainty must be None when "
                "valid is zero"
            )
        _validate_number(rate, f"{row_where}.rate", nullable=False)
        if not 0 <= rate <= 1:
            raise ValueError(f"{row_where}.rate must be between 0 and 1")
        _validate_number(
            uncertainty, f"{row_where}.uncertainty", nullable=False
        )
        if uncertainty < 0:
            raise ValueError(f"{row_where}.uncertainty must be non-negative")

    return windows, scenarios, items, data


def scale_delta(items) -> dict:
    """Compute per-scenario deltas between adjacent named stability scales.

    ``items`` must be a list of at least two mappings, each with exactly
    the keys ``name, result`` in that order.  ``name`` is a unique
    non-empty str and ``result`` is a complete :func:`stability_sum`
    result (schema ``climate-grid/ws-v1``); every member is validated
    against that contract.  Every result must share the same ``windows``,
    ``scenarios`` and ``items`` in the same order; ``windows`` and
    ``scenarios`` are taken from the first item.

    For every adjacent pair of items (in item order) and every scenario
    (in scenario order) a row is emitted: ``missing_delta`` is the later
    row's ``missing`` minus the earlier row's, ``level_deltas`` is the
    later row's ``levels`` minus the earlier row's elementwise (four
    ints), and only when both rows' ``rate`` and ``uncertainty`` are not
    ``None`` are ``rate_delta`` (later ``rate`` minus earlier ``rate``)
    and ``uncertainty`` (``hypot`` of the two uncertainties) computed;
    otherwise both are ``None``.

    The returned mapping uses the key order ``schema, scales, scenarios,
    data``; ``schema`` is ``climate-grid/wsd-v1``, ``scales`` lists the
    item names in item order and ``scenarios`` echoes the first item's
    result.  ``data`` follows the adjacent-pair-then-scenario order;
    each row uses the key order ``left, right, scenario, missing_delta,
    level_deltas, rate_delta, uncertainty`` with ``left``/``right`` the
    earlier/later item names.  Every output float is ``round(x, 12)``
    with negative zero normalized to ``0.0``.  The input is not
    modified.

    Raises ``TypeError`` for wrong container/item/argument types and
    ``ValueError`` for any other contract violation.
    """
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    if len(items) < 2:
        raise ValueError("items must contain at least 2 items")

    names: list[str] = []
    validated: list[list] = []
    seen_names: set[str] = set()
    for index, item in enumerate(items):
        where = f"items[{index}]"
        if not isinstance(item, dict):
            raise TypeError(f"{where} must be a dict")
        if tuple(item.keys()) != _STABILITY_SUM_ITEM_KEYS:
            raise ValueError(
                f"{where} must have exactly the keys name, result in order"
            )

        name = item["name"]
        if not isinstance(name, str):
            raise TypeError(f"{where}.name must be a str")
        if name == "":
            raise ValueError(f"{where}.name must be non-empty")
        if name in seen_names:
            raise ValueError(f"duplicate items name: {name!r}")
        seen_names.add(name)

        windows, scenarios, members, data = _validate_stability_sum(
            item["result"], where=f"{where}.result"
        )
        if not validated:
            first_windows = windows
            first_scenarios = scenarios
            first_members = members
        else:
            if windows != first_windows:
                raise ValueError(
                    "all items must share the same result windows in the "
                    "same order, taken from the first item"
                )
            if scenarios != first_scenarios:
                raise ValueError(
                    "all items must share the same result scenarios in the "
                    "same order, taken from the first item"
                )
            if members != first_members:
                raise ValueError(
                    "all items must share the same result items in the "
                    "same order, taken from the first item"
                )

        names.append(name)
        validated.append(data)

    rows = []
    for index in range(len(validated) - 1):
        left_data = validated[index]
        right_data = validated[index + 1]
        for s_index, scenario in enumerate(first_scenarios):
            left = left_data[s_index]
            right = right_data[s_index]
            missing_delta = _round_output(right["missing"] - left["missing"])
            level_deltas = [
                right_count - left_count
                for left_count, right_count in zip(
                    left["levels"], right["levels"]
                )
            ]
            if (
                left["rate"] is None
                or left["uncertainty"] is None
                or right["rate"] is None
                or right["uncertainty"] is None
            ):
                rate_delta = None
                uncertainty = None
            else:
                rate_delta = _round_output(right["rate"] - left["rate"])
                uncertainty = _round_output(
                    math.hypot(left["uncertainty"], right["uncertainty"])
                )
            rows.append(
                {
                    "left": names[index],
                    "right": names[index + 1],
                    "scenario": scenario,
                    "missing_delta": missing_delta,
                    "level_deltas": level_deltas,
                    "rate_delta": rate_delta,
                    "uncertainty": uncertainty,
                }
            )

    return {
        "schema": _SCALE_DELTA_SCHEMA,
        "scales": names,
        "scenarios": list(first_scenarios),
        "data": rows,
    }

